void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    if (!dev)
        return NULL;

    if (dev->dma_mask && *dev->dma_mask)
        flags &= ~GFP_DMA;

    if (flags & GFP_DMA) {
        void *cpu_addr = kmalloc(size, flags);
        if (!cpu_addr)
            return NULL;
        *dma_handle = virt_to_dma(dev, cpu_addr);
        return cpu_addr;
    } else {
        struct page *page = alloc_pages(flags, get_order(size));
        if (!page)
            return NULL;
        *dma_handle = page_to_phys(page);
        return page_address(page);
    }
}

void *allocate_coherent_dma_memory(struct device *dev, size_t size,
                                   dma_addr_t *dma_handle, gfp_t flags,
                                   struct dma_attrs *attrs) {
    void *memory;

    if (!dev || !dma_handle)
        return NULL;

    flags &= ~(__GFP_HIGHMEM | __GFP_DMA | __GFP_DMA32);

    if (dev->dma_mask && *dev->dma_mask <= DMA_BIT_MASK(32)) {
        flags |= __GFP_DMA32;
    } else {
        flags |= __GFP_DMA;
    }

    memory = dma_alloc_coherent(dev, size, dma_handle, flags, attrs);
    return memory;
}

void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    if (!dev)
        return NULL;

    if (dev->dma_mask && *dev->dma_mask < DMA_BIT_MASK(32))
        flags |= GFP_DMA;

    if (attrs && dma_get_attr(DMA_ATTR_FORCE_CONTIGUOUS, attrs)) {
        return __dma_alloc_from_contiguous(dev, size, 1, dma_handle, flags, attrs);
    }

    return __dma_alloc(dev, size, dma_handle, flags, attrs);
}

void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    if (!dev || !dma_handle)
        return NULL;

    /* Adjust flags based on device's DMA mask if needed */
    if (dev->dma_mask && *dev->dma_mask < DMA_BIT_MASK(32))
        flags &= ~__GFP_HIGHMEM;

    return __dma_alloc(dev, size, dma_handle, flags, attrs, true);
}

void *dma_alloc_coherent(struct device *dev, size_t size, dma_addr_t *dma_handle, gfp_t flags, struct dma_attrs *attrs)
{
    struct page *pages = NULL;
    void *ret = NULL;

    if (!dev)
        return NULL;

    if (dma_supported(dev, DMA_BIT_MASK(64)))
        flags |= GFP_DMA;
    else
        flags |= GFP_DMA32;

    pages = alloc_pages(flags, get_order(size));
    if (!pages)
        return NULL;

    ret = page_address(pages);
    if (!ret)
        goto free_pages;

    *dma_handle = page_to_phys(pages);

    return ret;

free_pages:
    __free_pages(pages, get_order(size));
    return NULL;
}
